export function ArchitectureVisual({variant=0}:{variant?:number}){return <div className={'architecture visual-'+variant} aria-label="Abstract connected software architecture"><div className="visual-grid"/><svg viewBox="0 0 600 540" role="img" aria-label="Connected layers of a software system"><defs><linearGradient id={'line-'+variant} x1="0" y1="0" x2="1" y2="1"><stop stopColor="#c5e9dc"/><stop offset="1" stopColor="#56a89b"/></linearGradient></defs><g className="architecture-lines" fill="none" stroke={'url(#line-'+variant+')'} strokeWidth="1.1">{[0,1,2,3].map((v)=><g key={v} transform={'translate(0 '+v*48+')'}><path d="M300 92 L488 198 L300 306 L112 198 Z"/><path d="M112 198 L112 228 L300 336 L488 228 L488 198"/><path d="M300 306 V336"/></g>)}<path strokeDasharray="4 8" d="M300 35 V480 M55 230 L300 370 L545 230"/><path d="M112 294 L55 326 V388 L160 449 M488 294 L545 326 V388 L440 449"/></g><g className="core-node"><path d="M300 149 L361 184 L300 219 L239 184 Z" fill="#b8dccc"/><path d="M239 184 V225 L300 260 V219 Z" fill="#65988b"/><path d="M361 184 V225 L300 260 V219 Z" fill="#8bb6a6"/><path d="M275 184 L300 170 L325 184 L300 199 Z" fill="#153e35"/></g>{[[112,198],[488,246],[300,450],[55,326],[545,388],[300,35]].map(([x,y],i)=><circle className="data-node" style={{animationDelay:i*.6+'s'}} key={i} cx={x} cy={y} r="4" fill="#d4f4e4"/>)}<g fill="#9bb9ac" fontFamily="monospace" fontSize="9"><text x="37" y="189">INPUT / 01</text><text x="477" y="184">EXPERIENCE</text><text x="415" y="467">INFRASTRUCTURE</text><text x="262" y="506">SYSTEM.CONNECTED</text></g></svg><span className="visual-status"><i/> ARCHITECTURE IN MOTION</span></div>}
